import {gradeLabel} from './grades';
import type {RecordContent} from './records';
export const visionLogo='data:image/svg+xml;base64,';
export const educationHeader=()=>'<div class="education-brand"><div><small>المملكة العربية السعودية</small><strong>وزارة التعليم</strong></div><img src="'+visionLogo+'" alt="رؤية السعودية 2030"/></div>';

export const ministryReferenceLogo='data:image/png;base64,';
const escapeHeader=(value:unknown)=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
export function recordHeader(record:RecordContent){const classroom=record.classLabel||gradeLabel(record.grade)+(record.className?' '+record.className:'');return '<header class="record-cliche"><div class="record-cliche-brand"><img class="record-ministry-logo" src="'+ministryReferenceLogo+'" alt="وزارة التعليم"><div class="record-school"><strong>وزارة التعليم</strong><span>'+escapeHeader(record.schoolName||'اسم المدرسة')+'</span></div><img class="record-vision-logo" src="'+visionLogo+'" alt="رؤية السعودية 2030"></div><h1>'+escapeHeader(record.title)+'</h1></header><div class="record-cliche-details"><p>الفصل: '+escapeHeader(classroom)+'</p><strong>العام الدراسي 1448 هـ</strong></div><table class="record-cliche-meta" aria-label="بيانات الكشف"><thead><tr><th>العام الدراسي</th><th>الفصل</th><th>المادة</th></tr></thead><tbody><tr><td>1448 هـ</td><td>'+escapeHeader(classroom)+'</td><td>'+escapeHeader(record.subjectName||'—')+'</td></tr></tbody></table>';}
export const recordHeaderCss=`.record-cliche{position:relative;background:#0a3845;color:#fff;border:0!important;border-top:7px solid #38af80!important;border-radius:0 0 18px 18px;padding:26px 24px 35px!important;margin-bottom:30px!important}.record-cliche-brand{display:flex;align-items:center;justify-content:center;gap:18px;position:relative}.record-ministry-logo{width:102px;height:82px;object-fit:contain}.record-school{border-right:2px solid #2db8ce;padding-right:16px;display:grid;gap:6px;max-width:280px;text-align:right}.record-school strong{font-size:20px;color:#fff}.record-school span{color:#51c7c6;font-size:15px;overflow-wrap:anywhere}.record-vision-logo{width:87px;height:44px;object-fit:contain;margin-right:auto}.record-cliche h1{overflow-wrap:anywhere;position:relative;top:18px;margin:5px auto -42px!important;width:fit-content;max-width:95%;background:#0a3845;border:1px solid #37b482;border-radius:0 0 12px 12px;padding:7px 40px;font:700 24px/1.5 Tahoma,Arial,sans-serif!important;color:#fff}.record-cliche-details{text-align:center;line-height:1.7;margin:12px 0 18px;color:#364b4d;font-size:14px}.record-cliche-details strong{color:#237fa5;font-size:14px}.record-cliche-meta{width:100%;border-collapse:collapse;table-layout:fixed;margin:16px 0 22px;background:#fff;font:13px/1.7 Tahoma,Arial,sans-serif;color:#173b35}.record-cliche-meta th,.record-cliche-meta td{border:1px solid #a2bcb1;text-align:center;padding:8px;overflow-wrap:anywhere;height:auto!important}.record-cliche-meta th{background:#38ac7c;color:#fff;font-size:13px;width:33.33%!important}.record-cliche-meta td{background:#fff;color:#183d35}.record-cliche-preview{border-radius:12px;overflow:hidden;padding:12px;background:#fff;margin:20px 0;border:1px solid #d5e2d9}.record-cliche-preview .record-cliche-meta{margin-bottom:0}@media(max-width:480px){.record-cliche{padding:20px 12px 30px!important}.record-cliche-brand{gap:9px;flex-wrap:wrap}.record-ministry-logo{width:80px;height:66px}.record-school{padding-right:10px;max-width:155px}.record-school strong{font-size:17px}.record-school span{font-size:13px}.record-vision-logo{width:68px;margin-right:0}.record-cliche h1{font-size:19px!important;padding:7px 18px}.record-cliche-meta th,.record-cliche-meta td{font-size:12px}}@media print{.record-cliche{break-inside:avoid}.record-cliche-details,.record-cliche-meta{break-inside:avoid}.record-cliche h1{font-size:23px!important}.record-cliche-meta th{background:#38ac7c!important;color:#fff!important}.record-cliche-meta td{font-size:12px!important;line-height:1.6}}`;
